<script setup>
import { ref, computed } from 'vue'
import Chart from '../components/Chart.vue'
import Trend from '../components/Trend.vue'
import Icon from '../components/Icon.vue'
import Donut from '../components/Donut.vue'
import { marketing, transactions, money } from '../data'
const emit = defineEmits(['action', 'download'])
const period = ref('1 Month'), metric = ref(0), query = ref(''), selected = ref([]), sort = ref(0), descending = ref(false)
const stats = [['Revenue','$622K','1.9%','wallet'],['Orders','5.14K','46.2%','cart'],['Avg. order value','$121.00','30.3%','card'],['Conversion rate','2.93%','21.7%','funnel']]
const factor = computed(() => ({'7 Days': .24,'1 Month':1,'3 Months':2.8,'6 Months':5.5})[period.value])
const graph = computed(() => marketing.map((v,i) => (metric.value === 0 ? v : metric.value === 1 ? 10 + Math.sin(i*.6)*4 + i*.25 : metric.value === 2 ? 14 + Math.sin(i*.9)*3 : 11 + Math.cos(i*.8)*4) * (period.value === '7 Days' ? .85 : 1)))
const rows = computed(() => transactions.filter(row => row.join(' ').toLowerCase().includes(query.value.toLowerCase())).toSorted((a,b) => {const av = sort.value === 6 ? a[4]*a[5] : a[sort.value], bv = sort.value === 6 ? b[4]*b[5] : b[sort.value]; return (typeof av === 'number' ? av-bv : String(av).localeCompare(String(bv))) * (descending.value ? -1 : 1) }))
function toggleAll(e) { selected.value = e.target.checked ? rows.value.map(r => r[0]) : [] }
function sortBy(i) { if (sort.value === i) descending.value = !descending.value; else { sort.value = i; descending.value = false } }
</script>
<template><div class="dashboard dashboard-seven">
  <div class="page-toolbar"><div class="segmented-control"><button v-for="p in ['7 Days','1 Month','3 Months','6 Months']" :key="p" :class="{active: period === p}" @click="period = p">{{ p }}</button></div><div class="flex"><button @click="$emit('download', {name:'marketing-report', rows:transactions, headings:['ID','Customer','Product','Status','Qty','Unit price']})"><Icon name="download"/>Download Report</button><button class="icon-button" aria-label="Report options" @click="emit('action', {title:'Report options',body:'Use Download Report to export the transactions as a CSV file.'})"><Icon name="more"/></button></div></div>
  <section class="panel marketing-chart"><div class="metric-tabs"><button v-for="(stat,i) in stats" :key="stat[0]" :class="{active: metric === i}" @click="metric = i"><span class="eyeline"><Icon :name="stat[3]" :size="13"/>{{ stat[0] }}</span><div><h2>{{ i === 0 ? '$' + Math.round(622 * factor) + 'K' : i === 1 ? (5.14 * factor).toFixed(2) + 'K' : stat[1] }}</h2><Trend :value="stat[2]" :negative="i > 1"/></div></button></div><Chart :values="graph" :max="25" :height="250" :labels="['Mar 30','Apr 4','Apr 9','Apr 14','Apr 19','Apr 24','Apr 29']" :y-labels="['25k','20k','15k','10k','5k','0']"/></section>
  <section class="panel marketing-breakdown grid three">
    <div><div class="section-title"><h3><Icon name="layers" :size="13"/>Lead Sources Breakdown</h3><button class="text-button" @click="emit('action',{title:'Lead sources',body:'Website: 1,445 leads. Paid Ads: 903 leads. Emails: 722 leads. Referral: 451 leads.'})">More details<Icon name="arrow" :size="13"/></button></div><div class="lead-sources"><Donut total="3,521" caption="total leads"/><ul class="donut-legend"><li v-for="(row,i) in [['Website','1,445'],['Paid Ads','903'],['Emails','722'],['Referral','451']]" :key="row[0]"><i :style="{background:['#ddd','#888','#555','#292929'][i]}"></i><span>{{row[0]}}</span><strong>{{row[1]}}</strong></li></ul></div></div>
    <div><div class="section-title"><h3><Icon name="users" :size="13"/>New Leads / Day</h3><button class="text-button" @click="emit('action',{title:'New leads',body:'3,381 new leads in the last 30 days, up 1.2% compared with the previous period.'})">View leads<Icon name="arrow" :size="13"/></button></div><div class="section-summary"><div><h2>{{Math.round(3381 * factor).toLocaleString()}}</h2><p>leads in last {{period === '7 Days' ? '7' : period === '1 Month' ? '30' : period === '3 Months' ? '90' : '180'}} days</p></div><Trend value="1.2%"/></div><Chart :values="[18,20,6,8,26,32,25,48,13,17,40,42,41,29,34,7,13,42,28,21,26,20,22,24,23,25]" :height="138" :max="55"/></div>
    <div><div class="section-title"><h3><Icon name="globe" :size="13"/>Campaign ROI Snapshot</h3><button class="text-button" @click="emit('action',{title:'Campaign ROI',body:'Ad spend: $43,000. Revenue: $212,000. Return on ad spend: 4.94x. Revenue retained: $169,000.'})">Full Snapshot<Icon name="arrow" :size="13"/></button></div><div class="roi-stats grid three"><div v-for="r in [['Spend','$43K'],['Revenue','$212K'],['ROAS','4.94x']]" :key="r[0]"><p>{{r[0]}}</p><h3>{{r[1]}}</h3></div></div><div class="section-title"><span>Spend vs return mix</span><strong>20% / 80%</strong></div><div class="roi-bar"><span></span><span></span></div><div class="grid two roi-bottom"><div><p><i class="status-dot gray"></i>Ad spend</p><h3>$43K</h3></div><div><p><i class="status-dot light"></i>Revenue retained</p><h3>$169K</h3></div></div></div>
  </section>
  <section class="panel transactions"><div class="panel-heading"><h3><Icon name="wallet" :size="14"/>Recent Transactions <small v-if="selected.length">({{selected.length}} selected)</small></h3><div class="flex"><label class="search-field"><Icon name="search"/><input v-model="query" placeholder="Search transactions…" aria-label="Search transactions"></label><button class="icon-button" aria-label="Table options" @click="emit('download',{name:'transactions',rows:rows,headings:['ID','Customer','Product','Status','Qty','Unit price']})"><Icon name="more"/></button></div></div><div class="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Select all transactions" :checked="rows.length > 0 && selected.length === rows.length" @change="toggleAll"></th><th v-for="(h,i) in ['ID','Customer','Product','Status','Qty','Unit Price','Total Revenue']" :key="h"><button class="sort-button" @click="sortBy(i)">{{h}}<span>⌃<br>⌄</span></button></th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row[0]" :class="{ selected: selected.includes(row[0]) }"><td><input type="checkbox" v-model="selected" :value="row[0]" :aria-label="'Select transaction ' + row[0]"></td><td class="muted">#{{row[0]}}</td><td>{{row[1]}}</td><td class="muted">{{row[2]}}</td><td><span class="status-pill" :class="row[3].toLowerCase()"><Icon :name="row[3] === 'Success' ? 'check' : row[3] === 'Pending' ? 'clock' : 'minus'" :size="12"/>{{row[3]}}</span></td><td>{{row[4]}}</td><td>{{money(row[5])}}</td><td>{{money(row[4]*row[5])}}</td><td><button class="text-button row-action" :aria-label="'Details for transaction ' + row[0]" @click="emit('action',{title:'Transaction #' + row[0],body:`${row[1]} · ${row[2]} · ${row[4]} units · ${money(row[4]*row[5])} · ${row[3]}`})"><Icon name="more"/></button></td></tr><tr v-if="!rows.length"><td colspan="9" class="empty-state">No transactions match “{{query}}”.</td></tr></tbody></table></div></section>
</div></template>
